window.AUTH=window.AUTH||{};window.AUTH["23-939"]={"d":"23-939","id":"2023/23-939","n":"Trump v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Donald J. Trump","date":"2024-03-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-939/303418/20240319150454815_23-939%20-%20Brief%20for%20Petitioner.pdf","side":"pet","n":53},{"k":"respondent","label":"Brief of respondent United States","date":"2024-04-08","url":"https://www.supremecourt.gov/DocketPDF/23/23-939/306999/20240408191803801_United%20States%20v.%20Trump%20final%20for%20filing.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner Donald J. Trump","date":"2024-04-15","url":"https://www.supremecourt.gov/DocketPDF/23/23-939/307578/20240415133854183_USSC%2023-939%20-%20Reply%20Brief%20of%20Petitioner.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r57_2dp3.pdf","tr":true,"items":[{"t":"case","label":"Anderson v. Creighton","cite":"483 U.S. 635","y":1987,"id":"1986/85-1520","sc":1,"ar":1,"sum":"The Court held that an officer of the law has qualified immunity from civil liability if the actions that officer took “could reasonably have been thought consistent” with the allegedly violated rights. Because Anderson could reasonably believe that his actions were legal, he is entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"44, 47"}},{"t":"case","label":"Ashcroft v. al-Kidd","cite":"563 U.S. 731","y":2011,"id":"2010/10-98","sc":1,"op":1,"sum":"The Court held that former Attorney General John Ashcroft was entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Barr v. Matteo","cite":"360 U.S. 564","y":1959,"id":"1958/350","sc":1,"sum":"Justice John M. Harlan delivered the judgement of the court, reversing the court of appeals. The plurality argued that the statements from the press release were absolutely privileged. Justice Felix Frankfurter, Justice Tom C. Clark, and Justice Charles E. Whittaker joined in the plurality.","sumSrc":"Oyez","by":{"0":"10, 46, 48"}},{"t":"case","label":"Blassingame v. Trump","cite":"87 F.4th 1","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/87/1/","op":3,"ar":14,"by":{"0":"9, 44","2":"6"}},{"t":"case","label":"Bradley v. Fisher","cite":"80 U.S. 335","y":1871,"id":"scdb/1871-141","sc":1,"op":1,"sum":"This was an action brought by Joseph H. Bradley, who was, in 1867, an attorney-at-law, practicing in the Supreme Court of the District of Columbia, against George P. Fisher, who was then one of the justices of that court, to recover damages alleged to have been sustained by the plaintiffj “by reason of the wilful, malicious, oppressive, and tyrannical acts and conduct” of the defendant, whereby the plaintiff was …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"sum":"Federal officials who perform adjudicatory, or other similar prosecutorial functions, cannot, however, be held liable for mere \"good faith\" judgment errors. The Court reasoned that the risk of making unconstitutional determinations is outweighed by the need to preserve independent judgement, through grants of absolute immunity to judges and other similarly situated decision makers.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Chi. & S. Air Lines v. Waterman S. S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"13, 47"}},{"t":"case","label":"City of Tahlequa v. Bond","cite":"595 U.S. 9","y":2021,"url":"https://supreme.justia.com/cases/federal/us/595/9/","sc":1,"by":{"0":"46"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"op":10,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"14-15, 18-19, 27, 43","1":"10, 24, 40"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"District of Columbia v. Wesby","cite":"583 U.S. 48","y":2018,"id":"2017/15-1485","sc":1,"sum":"The Court decided that (1) officers had probable cause to arrest a number of partygoers for unlawful entry under D.C. law under the totality of the circumstances, and (2) that the officers were entitled to qualified immunity because their actions were not clearly unlawful at the time.","sumSrc":"Oyez","by":{"0":"46-47"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"op":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","2":"22"}},{"t":"case","label":"Ferri v. Ackerman","cite":"444 U.S. 193","y":1979,"id":"1979/78-5981","sc":1,"op":1,"sum":"An attorney appointed by a federal judge to represent an indigent defendant in a federal criminal trial is not, as a matter of federal law, entitled to absolute immunity in a state malpractice suit brought against him by his former client.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Filarsky v. Delia","cite":"566 U.S. 377","y":2012,"id":"2011/10-1018","sc":1,"op":1,"sum":"The Court found that a private attorney retained by a governmental agency is not prevented from claiming qualified immunity simply because they are not a full-time employee of the agency.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"op":2,"ar":11,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"8, 12-13, 20, 32, 37, 39","1":"26, 38","2":"6, 20-21"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":1,"ar":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"24","2":"2, 18"}},{"t":"case","label":"Gregoire v. Biddle","cite":"177 F.2d 579","y":1949,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/177/579/","op":1,"by":{"0":"27, 48"}},{"t":"case","label":"Hammerschmidt v. United States","cite":"265 U.S. 182","y":1924,"id":"scdb/1923-145","sc":1,"sum":"1. Section 37 of the Criminal Code (Rev. Stats., § 540) punishing conspiracy to defraud.the United StAtes in any manner or fok any purpose,\" does not embrace a conspiracy to defeat the pur-pose of the Selective Draft Act by inducing persons-to refuse to register under it.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"op":42,"sum":"Noting that we have “refused to draw functional lines finer than history and reason would support”.","sumSrc":"opinion","by":{"0":"45, 48, 50"}},{"t":"case","label":"Kendall v. U.S. ex rel. Stokes","cite":"37 U.S. 524","y":1838,"id":"scdb/1838-042","sc":1,"sum":"Contracts for carrying the mail of the United States, were made by S. & S., with the postmaster general of the United States, out of which certain allowances and credits were made in favour of S. & S., by that officer; and the amount of the. same was passed to the credit of S. & S., with the general post office. The successor of the postmaster general struck out the allowances and credits in the accounts, and thus a …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"12, 18","2":"6"}},{"t":"case","label":"Martin v. Mott","cite":"25 U.S. 19","y":1827,"id":"scdb/1827-009","sc":1,"ar":2,"sum":"This was an action of replevin, originally brought in the Supreme Court of New-York by the defendant in error, Mott, against the plaintiff in error, Martin, to which an avowry was filed, containing, substantially, the following allegations: That on the 18th of June, 1812, and from thence until the 25th of December, 1814, there was public and open war between the United States of America, and the United Kingdom of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11-12, 15, 18, 30, 47","2":"5-6"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"op":1,"ar":1,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"MCI Telecommunications Corp. v. American Telephone & Telegraph Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Mississippi v. Johnson","cite":"71 U.S. 475","y":1866,"id":"1850-1900/71us475","sc":1,"op":1,"ar":2,"sum":"The Court held that it had \"no jurisdiction of a bill to enjoin the President in the performance of his official duties....\" The Court held that the duties of the President as required by the Reconstruction Acts were \"in no sense ministerial,\" and that a judicial attempt to interfere with the performance of such duties would be \"an absurd and excessive extravagance.\" The Court noted that if the President chose to ignore the injunction, the judiciary would be unable to enforce the order.","sumSrc":"Oyez","by":{"0":"12, 31-32","2":"6"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"op":4,"ar":3,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"0":"3, 28, 37","1":"19","2":"22"}},{"t":"case","label":"Moyer v. Peabody","cite":"212 U.S. 78","y":1909,"id":"scdb/1908-062","sc":1,"sum":"What is due process of law depends on circumstances, and varies with the subject-matter and necessities of the situation.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Newdow v. Roberts","cite":"603 F.3d 1002","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/603/1002/","by":{"0":"14"}},{"t":"case","label":"NFIB v. OSHA","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"0":"8, 24, 38"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"op":44,"sum":"Noting that we have “refused to draw functional lines finer than history and reason would support”.","sumSrc":"opinion","by":{"0":"2-4, 7-8, 10, 14-16, 19-20, 24-27, 28-29, 32, 35-36, 41-45, 48, 50","1":"5, 9, 14, 18-20, 39, 40, 42","2":"1, 5-6, 8, 13, 16, 23"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"0":"46","2":"24"}},{"t":"case","label":"Pierson v. Ray","cite":"386 U.S. 547","y":1967,"id":"1966/79","sc":1,"op":2,"sum":"Petitioners,t,'members of a group of white and Negro clergymen on a \"prayer pilgrimage\" to promote racial integration, attempted to use a segregated interstate bus terminal waiting room in Jackson, Mississippi, in 1961. They were arrested by respondent policemen and charged with conduct breaching the peace in violation of § 2087.5 of the Mississippi Code which this Court, in 1965, held unconstitutional in Thomas v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 38, 48"}},{"t":"case","label":"Public Citizen v. U.S. Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"op":2,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 37-38","1":"26"}},{"t":"case","label":"Scheuer v. Rhodes","cite":"416 U.S. 232","y":1974,"id":"1973/72-914","sc":1,"sum":"Petitioners, the personal representatives of the estates of students who were killed on the campus of*a state-controlled university, brought these damages actions under 42 U. S. C. § 1983 against the Governor, the Adjutant General of the Ohio National Guard, various other Guard officers and enlisted members, and the university president, charging that those officials, acting under color of state law, \"intentionally, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 46"}},{"t":"case","label":"Seila Law, LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"op":10,"ar":2,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"0":"24","1":"11","2":"1, 3, 7, 10, 16"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Spalding v. Vilas","cite":"161 U.S. 483","y":1896,"id":"scdb/1895-154","sc":1,"op":2,"sum":"It was the duty of the Postmaster General to cause all cheques or warrants issued under the authority of the act of March 3, 1883, c. 119, 22 Stat. 487, and of the act of August 4, 1886, c. 903, § 8, 24 Stat. 256, 307, 308, to be sent directly to the claimants, and it was his right to call their attention to the provisions of the act of 1883; and if the legislation to which attention was thus invited worked injury …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25, 41, 48","1":"43","2":"14"}},{"t":"case","label":"Trump v. Anderson","cite":"144 S. Ct. 662","y":2024,"id":"2023/23-719","sc":1,"sum":"Because the Constitution makes Congress, rather than the States, responsible for enforcing Section 3 of the Fourteenth Amendment against federal officeholders and candidates, the Colorado Supreme Court erred in ordering former President Trump excluded from the 2024 Presidential primary ballot.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"7, 24","1":"17","2":"10"}},{"t":"case","label":"Trump v. Mazars USA, LLP","cite":"591 U.S. 848","y":2020,"id":"2019/19-715","sc":1,"op":12,"sum":"Noting only “two exceptions to the President's unrestricted removal power”.","sumSrc":"opinion","by":{"0":"16, 43","1":"9"}},{"t":"case","label":"Trump v. Vance","cite":"140 S. Ct. 2412","y":2020,"id":"2019/19-635","sc":1,"sum":"The Court held that Article II and the Supremacy Clause neither categorically preclude, nor require a heightened standard for, the issuance of a state criminal subpoena to a sitting President.","sumSrc":"Oyez","by":{"0":"3, 14-15, 17, 26-27, 43","1":"12, 14, 15, 22, 40, 42","2":"5"}},{"t":"case","label":"United States v. Johnson","cite":"383 U.S. 169","y":1966,"id":"1965/25","sc":1,"op":1,"sum":"Respondent, a former Congressman, was convicted on several counts of violating the conflict of interest statute (18 U. S. C. §281) and on one count of conspiring to defraud the United States (18 U. S. C. § 371). The conspiracy charge involved an alleged agreement whereby respondent and another Congressman would attempt to influence the Justice Department to dismiss pending savings and loan company mail fraud …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 41","1":"44","2":"14, 23"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"op":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24","1":"20"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"568 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"usc","label":"18 U.S.C. § 241","url":"https://www.law.cornell.edu/uscode/text/18/241","stext":{"head":"§241. Conspiracy against rights","paras":[[0,"If two or more persons conspire to injure, oppress, threaten, or intimidate any person in any State, Territory, Commonwealth, Possession, or District in the free exercise or enjoyment of any right or privilege secured to him by the Constitution or laws of the United States, or because of his having so exercised the same; or"],[0,"If two or more persons go in disguise on the highway, or on the premises of another, with intent to prevent or hinder his free exercise or enjoyment of any right or privilege so secured—"],[0,"They shall be fined under this title or imprisoned not more than ten years, or both; and if death results from the acts committed in violation of this section or if such acts include kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill, they shall be fined under this title or imprisoned for any term of years or for life, or both, or may be sentenced to death."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/241?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§241. Conspiracy against rights","tname":"Crimes and Criminal Procedure","by":{"0":"39","1":"25"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","stext":{"head":"§371. Conspiracy to commit offense or to defraud United States","paras":[[0,"If two or more persons conspire either to commit any offense against the United States, or to defraud the United States, or any agency thereof in any manner or for any purpose, and one or more of such persons do any act to effect the object of the conspiracy, each shall be fined under this title or imprisoned not more than five years, or both."],[0,"If, however, the offense, the commission of which is the object of the conspiracy, is a misdemeanor only, the punishment for such conspiracy shall not exceed the maximum punishment provided for such misdemeanor."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/371?type=usc&year=mostrecent&link-type=html"},"head":"§371. Conspiracy to commit offense or to defraud United States","tname":"Crimes and Criminal Procedure","by":{"0":"39","1":"25","2":"17"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(c)(2)","(k)","(c)"],"stext":{"head":"§1512. Tampering with a witness, victim, or an informant","paras":[[0,"(a)(1) Whoever kills or attempts to kill another person, with intent to—"],[1,"(A) prevent the attendance or testimony of any person in an official proceeding;"],[1,"(B) prevent the production of a record, document, or other object, in an official proceeding; or"],[1,"(C) prevent the communication by any person to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation, parole, or release pending judicial proceedings;"],[0,"shall be punished as provided in paragraph (3)."],[0,"(2) Whoever uses physical force or the threat of physical force against any person, or attempts to do so, with intent to—"],[1,"(A) influence, delay, or prevent the testimony of any person in an official proceeding;"],[1,"(B) cause or induce any person to—"],[2,"(i) withhold testimony, or withhold a record, document, or other object, from an official proceeding;"],[2,"(ii) alter, destroy, mutilate, or conceal an object with intent to impair the integrity or availability of the object for use in an official proceeding;"],[2,"(iii) evade legal process summoning that person to appear as a witness, or to produce a record, document, or other object, in an official proceeding; or"],[2,"(iv) be absent from an official proceeding to which that person has been summoned by legal process; or"],[1,"(C) hinder, delay, or prevent the communication to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation, supervised release, parole, or release pending judicial proceedings;"],[0,"shall be punished as provided in paragraph (3)."],[0,"(3) The punishment for an offense under this subsection is—"],[1,"(A) in the case of a killing, the punishment provided in sections 1111 and 1112;"],[1,"(B) in the case of—"],[2,"(i) an attempt to murder; or"],[2,"(ii) the use or attempted use of physical force against any person;"],[1,"imprisonment for not more than 30 years; and"],[1,"(C) in the case of the threat of use of physical force against any person, imprisonment for not more than 20 years."],[0,"(b) Whoever knowingly uses intimidation, threatens, or corruptly persuades another person, or attempts to do so, or engages in misleading conduct toward another person, with intent to—"],[1,"(1) influence, delay, or prevent the testimony of any person in an official proceeding;"],[1,"(2) cause or induce any person to—"],[2,"(A) withhold testimony, or withhold a record, document, or other object, from an official proceeding;"],[2,"(B) alter, destroy, mutilate, or conceal an object with intent to impair the object's integrity or availability for use in an official proceeding;"],[2,"(C) evade legal process summoning that person to appear as a witness, or to produce a record, document, or other object, in an official proceeding; or"],[2,"(D) be absent from an official proceeding to which such person has been summoned by legal process; or"],[1,"(3) hinder, delay, or prevent the communication to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation 1 supervised release,,1 parole, or release pending judicial proceedings;"],[0,"shall be fined under this title or imprisoned not more than 20 years, or both."],[0,"(c) Whoever corruptly—"],[1,"(1) alters, destroys, mutilates, or conceals a record, document, or other object, or attempts to do so, with the intent to impair the object's integrity or availability for use in an official proceeding; or"],[1,"(2) otherwise obstructs, influences, or impedes any official proceeding, or attempts to do so,"],[0,"shall be fined under this title or imprisoned not more than 20 years, or both."],[0,"(d) Whoever intentionally harasses another person and thereby hinders, delays, prevents, or dissuades any person from—"],[1,"(1) attending or testifying in an official proceeding;"],[1,"(2) reporting to a law enforcement officer or judge of the United States the commission or possible commission of a Federal offense or a violation of conditions of probation 1 supervised release,,1 parole, or release pending judicial proceedings;"],[1,"(3) arresting or seeking the arrest of another person in connection with a Federal offense; or"],[1,"(4) causing a criminal prosecution, or a parole or probation revocation proceeding, to be sought or instituted, or assisting in such prosecution or proceeding;"],[0,"or attempts to do so, shall be fined under this title or imprisoned not more than 3 years, or both."],[0,"(e) In a prosecution for an offense under this section, it is an affirmative defense, as to which the defendant has the burden of proof by a preponderance of the evidence, that the conduct consisted solely of lawful conduct and that the defendant's sole intention was to encourage, induce, or cause the other person to testify truthfully."],[0,"(f) For the purposes of this section—"],[1,"(1) an official proceeding need not be pending or about to be instituted at the time of the offense; and"],[1,"(2) the testimony, or the record, document, or other object need not be admissible in evidence or free of a claim of privilege."],[0,"(g) In a prosecution for an offense under this section, no state of mind need be proved with respect to the circumstance—"],[1,"(1) that the official proceeding before a judge, court, magistrate judge, grand jury, or government agency is before a judge or court of the United States, a United States magistrate judge, a bankruptcy judge, a Federal grand jury, or a Federal Government agency; or"],[1,"(2) that the judge is a judge of the United States or that the law enforcement officer is an officer or employee of the Federal Government or a person authorized to act for or on behalf of the Federal Government or serving the Federal Government as an adviser or consultant."],[0,"(h) There is extraterritorial Federal jurisdiction over an offense under this section."],[0,"(i) A prosecution under this section or section 1503 may be brought in the district in which the official proceeding (whether or not pending or about to be instituted) was intended to be affected or in the district in which the conduct constituting the alleged offense occurred."],[0,"(j) If the offense under this section occurs in connection with a trial of a criminal case, the maximum term of imprisonment which may be imposed for the offense shall be the higher of that otherwise provided by law or the maximum term that could have been imposed for any offense charged in such case."],[0,"(k) Whoever conspires to commit any offense under this section shall be subject to the same penalties as those prescribed for the offense the commission of which was the object of the conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1512?type=usc&year=mostrecent&link-type=html"},"head":"§1512. Tampering with a witness, victim, or an informant","tname":"Crimes and Criminal Procedure","by":{"0":"39, 39","1":"26, 26, 26","2":"17"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"const","label":"Article I, Section 3, Clause 7","text":"Judgment in Cases of Impeachment shall not extend further than to removal from Office, and disqualification to hold and enjoy any Office of honor, Trust or Profit under the United States: but the Party convicted shall nevertheless be liable and subject to Indictment, Trial, Judgment and Punishment, according to Law.","by":{"0":"16, 22, 35"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"0":"10, 13, 26","2":"3"}},{"t":"usc","label":"28 U.S.C. § 458","url":"https://www.law.cornell.edu/uscode/text/28/458","stext":{"head":"§458. Relative of justice or judge ineligible to appointment","paras":[[0,"(a)(1) No person shall be appointed to or employed in any office or duty in any court who is related by affinity or consanguinity within the degree of first cousin to any justice or judge of such court."],[0,"(2) With respect to the appointment of a judge of a court exercising judicial power under article III of the United States Constitution (other than the Supreme Court), subsection (b) shall apply in lieu of this subsection."],[0,"(b)(1) In this subsection, the term—"],[1,"(A) \"same court\" means—"],[2,"(i) in the case of a district court, the court of a single judicial district; and"],[2,"(ii) in the case of a court of appeals, the court of appeals of a single circuit; and"],[1,"(B) \"member\"—"],[2,"(i) means an active judge or a judge retired in senior status under section 371(b); and"],[2,"(ii) shall not include a retired judge, except as described under clause (i)."],[0,"(2) No person may be appointed to the position of judge of a court exercising judicial power under article III of the United States Constitution (other than the Supreme Court) who is related by affinity or consanguinity within the degree of first cousin to any judge who is a member of the same court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/458?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§458. Relative of justice or judge ineligible to appointment","tname":"Judiciary and Judicial Procedure","by":{"0":"38","1":"27, 28"}},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Burdick v. United States","cite":"236 U.S. 79","y":1915,"id":"scdb/1914-243","sc":1,"sum":"Acceptance, as well as delivery, of a pardon is essential to its validity; if rejected by the person to whom it is tendered the court has no power to force it on him. United States v. Wilson, 7Pet. 150.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Cheney v. United States Dist. Ct.","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"op":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"1":"19, 22"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"op":2,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"1":"11, 39"}},{"t":"case","label":"Dennis v. Sparks","cite":"449 U.S. 24","y":1980,"id":"1980/79-1186","sc":1,"op":1,"sum":"The action against the private parties accused of conspiring with the judge is not subject to dismissal. Private persons, jointly engaged with state officials in a challenged action, are acting \"under color\" of law for purposes of § 1983 actions. And the judge's immunity from damages liability for an official act that was allegedly the product of a corrupt conspiracy involving bribery of the judge does not change …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Dowling v. United States","cite":"493 U.S. 342","y":1990,"id":"1989/88-6025","sc":1,"sum":"Petitioner Dowling was convicted of robbing a Virgin Islands bank while wearing a ski mask and carrying a small pistol. Relying on Federal Rule of Evidence 404(b)-which provides that evidence of other crimes, wrongs, or acts may be admissible against a defendant for purposes other than character evidence-the Government introduced at trial the testimony of one Henry, who stated that a similarly masked and armed …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Garcetti v. Ceballos","cite":"547 U.S. 410","y":2006,"id":"2005/04-473","sc":1,"sum":"In a 5-to-4 decision authored by Justice Anthony Kennedy, the Supreme Court held that speech by a public official is only protected if it is engaged in as a private citizen, not if it is expressed as part of the official's public duties.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Gravel v. United States","cite":"408 U.S. 606","y":1972,"id":"1971/71-1017","sc":1,"sum":"The Court held that because the work of aides was critical to the performance of legislative tasks and duties, they were nothing less than legislators' \"alter egos\" and thus immune from subpoenas by the Speech and Debate Clause. Aides were exempted from grand jury questioning so long as Senators invoked the privilege on their behalf.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Huddleston v. United States","cite":"485 U.S. 681","y":1988,"id":"1987/87-6","sc":1,"op":1,"sum":"The Court held that requiring the trial court to make a preliminary ruling before admitting character evidence is contrary to Article IV of the Federal Rules of Evidence.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"op":1,"sum":"The Court held that prosecutors have the same absolute immunity under Section 1983 that they had under common law in malicious prosecution suits.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"587 U.S. 802","y":2019,"id":"2018/17-1702","sc":1,"sum":"The Court held that Manhattan Community Access Corp, which operates public access channels, is not a state actor subject to constitutional liability.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Medellin v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"1":"12, 39"}},{"t":"case","label":"Nardone v. United States","cite":"302 U.S. 379","y":1937,"id":"scdb/1937-010","sc":1,"op":3,"ar":1,"sum":"1. In view of the provisions of § 605 of the Communications Act of 1934, 47 U. S. C. § 605, evidence obtained by federal agents by tapping telephone wires and intercepting messages is not admissible in a criminal trial in the federal district court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Nixon v. Administrator of Gen. Servs.","cite":"433 U.S. 425","y":1977,"id":"1976/75-1605","sc":1,"op":1,"sum":"The Court held that the act did not violate any of Nixon’s relevant constitutional rights. Justice Brennan first determined that the district court correctly limited the scope of its review to the constitutional consequences of the archival screenings because the Administrator had not yet promulgated any regulations.","sumSrc":"Oyez","by":{"1":"12, 18"}},{"t":"case","label":"Nixon v. United States","cite":"506 U.S. 224","y":1993,"id":"1992/91-740","sc":1,"sum":"The Court held that Senate Rule XI was not subject to judicial review because the \"Senate shall have sole Power to try any impeachments.\"","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"op":1,"sum":"Respondents, 17 black and two white residents of Cairo, Illinois, brought a civil rights class action against petitioners, a magistrate and a circuit court jfidge, who allegedly engaged under'color of state law, in a continuing pattern and practice of conduct consisting of illegal bond-setting, sentencing, and jury-fee practices in criminal cases, which assertedly deprived respondents and members of their class of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Sale v. Haitian Centers Council","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"op":1,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"op":4,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"1":"39","2":"7"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"1":"20, 21"}},{"t":"case","label":"United States v. Blagojevich","cite":"794 F.3d 729","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/729/","by":{"1":"41"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","op":13,"sum":"Stating that nothing before the court showed that the document in question “contain[ed] any matter the disclosure of which would endanger the public safety”.","sumSrc":"opinion","by":{"1":"13"}},{"t":"case","label":"United States v. Butenko","cite":"494 F.2d 593","y":1974,"url":"https://www.courtlistener.com/c/F.2d/494/593/","sum":"Interpreting a surveillance statute to permit the President to order foreign wiretaps because the contrary interpretation might have interfered with the “President’s effective performance of his duties in the foreign affairs field”.","sumSrc":"brief:1","by":{"1":"30"}},{"t":"case","label":"Unites States v. Claiborne","cite":"727 F.2d 842","y":1984,"url":"https://www.courtlistener.com/c/F.2d/727/842/","by":{"1":"33"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"op":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"United States v. Haldeman","cite":"559 F.2d 31","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/559/31/","ar":1,"sum":"Describing use of the CIA to obstruct the FBI’s investigation of the Watergate burglary.","sumSrc":"brief:1","by":{"1":"15, 47"}},{"t":"case","label":"United States v. Hastings","cite":"681 F.2d 706","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/681/706/","by":{"1":"33"}},{"t":"case","label":"United States v. Isaacs","cite":"493 F.2d 1124","y":1974,"url":"https://www.courtlistener.com/c/F.2d/493/1124/","by":{"1":"33"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"op":7,"ar":1,"sum":"Authored by Justice David Souter, the Court ruled that the standard of notice that the Court of Appeals employed was higher than the Constitution requires and too demanding.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"op":2,"by":{"1":"12"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"op":11,"sum":"Rejecting unanimously a similar argument in the analogous executive privilege context.","sumSrc":"opinion","by":{"1":"12, 15, 16, 19, 21, 22, 30, 33"}},{"t":"case","label":"United States v. Rostenkowski","cite":"59 F.3d 1291","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/59/1291/","by":{"1":"48"}},{"t":"case","label":"United States v. Sun-Diamond Growers","cite":"526 U.S. 398","y":1999,"id":"1998/98-131","sc":1,"ar":1,"sum":"The Court held that to sustain conviction for federal bribery there must be a clear quid pro quo link between the gratuity received and performance of a specific past, present, or future \"official\" act. The Court reasoned that a statutory interpretation that punished the giving of any gifts to public officials would not fit comfortably with the legislation's spirit and traditions.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"op":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Wayte v. United States","cite":"470 U.S. 598","y":1985,"id":"1984/83-1292","sc":1,"ar":1,"sum":"The Supreme Court held, 7-to-2, that the government's passive enforcement policy was constitutional.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Wisconsin v. Mitchell","cite":"508 U.S. 476","y":1993,"id":"1992/92-515","sc":1,"op":3,"ar":1,"sum":"The Court found that the Wisconsin statute paralleled antidiscrimination laws which had been found to comply with the First Amendment. It also determined that the consequences for the victim and the community tended to be more severe, when the victim of a crime was chosen on account of his or her race.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Yates v. Lansing","cite":"5 Johns. 282","y":1810,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Johns./5/282/","by":{"1":"43"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"op":15,"ar":2,"sum":"Noting “the poverty of really useful and unambiguous authority applicable to concrete problems of executive power”.","sumSrc":"opinion","by":{"1":"4, 10-12, 39, 40","2":"2, 4, 6"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"op":3,"sum":"Holding that the President has “exclusive power . . . to control recognition determinations”.","sumSrc":"opinion","by":{"1":"11, 30","2":"3, 6-8"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"47, 48"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"3, 21"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"22"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(b)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"1":"26","2":"20"}},{"t":"law","label":"Federal Advisory Committee Act, Pub. L. No. 92-463","url":"https://www.govinfo.gov/link/statute/86/770","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","stext":{"head":"§201. Bribery of public officials and witnesses","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) the term \"public official\" means Member of Congress, Delegate, or Resident Commissioner, either before or after such official has qualified, or an officer or employee or person acting for or on behalf of the United States, or any department, agency or branch of Government thereof, including the District of Columbia, in any official function, under or by authority of any such department, agency, or branch of Government, or a juror;"],[1,"(2) the term \"person who has been selected to be a public official\" means any person who has been nominated or appointed to be a public official, or has been officially informed that such person will be so nominated or appointed; and"],[1,"(3) the term \"official act\" means any decision or action on any question, matter, cause, suit, proceeding or controversy, which may at any time be pending, or which may by law be brought before any public official, in such official's official capacity, or in such official's place of trust or profit."],[0,"(b) Whoever—"],[1,"(1) directly or indirectly, corruptly gives, offers or promises anything of value to any public official or person who has been selected to be a public official, or offers or promises any public official or any person who has been selected to be a public official to give anything of value to any other person or entity, with intent—"],[2,"(A) to influence any official act; or"],[2,"(B) to influence such public official or person who has been selected to be a public official to commit or aid in committing, or collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) to induce such public official or such person who has been selected to be a public official to do or omit to do any act in violation of the lawful duty of such official or person;"],[1,"(2) being a public official or person selected to be a public official, directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity, in return for:"],[2,"(A) being influenced in the performance of any official act;"],[2,"(B) being influenced to commit or aid in committing, or to collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) being induced to do or omit to do any act in violation of the official duty of such official or person;"],[1,"(3) directly or indirectly, corruptly gives, offers, or promises anything of value to any person, or offers or promises such person to give anything of value to any other person or entity, with intent to influence the testimony under oath or affirmation of such first-mentioned person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or with intent to influence such person to absent himself therefrom;"],[1,"(4) directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity in return for being influenced in testimony under oath or affirmation as a witness upon any such trial, hearing, or other proceeding, or in return for absenting himself therefrom;"],[1,"shall be fined under this title or not more than three times the monetary equivalent of the thing of value, whichever is greater, or imprisoned for not more than fifteen years, or both, and may be disqualified from holding any office of honor, trust, or profit under the United States."],[0,"(c) Whoever—"],[1,"(1) otherwise than as provided by law for the proper discharge of official duty—"],[2,"(A) directly or indirectly gives, offers, or promises anything of value to any public official, former public official, or person selected to be a public official, for or because of any official act performed or to be performed by such public official, former public official, or person selected to be a public official; or"],[2,"(B) being a public official, former public official, or person selected to be a public official, otherwise than as provided by law for the proper discharge of official duty, directly or indirectly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of any official act performed or to be performed by such official or person;"],[1,"(2) directly or indirectly, gives, offers, or promises anything of value to any person, for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or for or because of such person's absence therefrom;"],[1,"(3) directly or indirectly, demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon any such trial, hearing, or other proceeding, or for or because of such person's absence therefrom;"],[1,"shall be fined under this title or imprisoned for not more than two years, or both."],[0,"(d) Paragraphs (3) and (4) of subsection (b) and paragraphs (2) and (3) of subsection (c) shall not be construed to prohibit the payment or receipt of witness fees provided by law, or the payment, by the party upon whose behalf a witness is called and receipt by a witness, of the reasonable cost of travel and subsistence incurred and the reasonable value of time lost in attendance at any such trial, hearing, or proceeding, or in the case of expert witnesses, a reasonable fee for time spent in the preparation of such opinion, and in appearing and testifying."],[0,"(e) The offenses and penalties prescribed in this section are separate from and in addition to those prescribed in sections 1503, 1504, and 1505 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/201?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":2,"head":"§201. Bribery of public officials and witnesses","tname":"Crimes and Criminal Procedure","by":{"1":"26, 28"}},{"t":"usc","label":"18 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/18/202","subs":["(c)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/18/227","stext":{"head":"§227. Wrongfully influencing a private entity's employment decisions by a Member of Congress or an officer or employee of the legislative or executive branch","paras":[[0,"(a) Whoever, being a covered government person, with the intent to influence, solely on the basis of partisan political affiliation, an employment decision or employment practice of any private entity—"],[1,"(1) takes or withholds, or offers or threatens to take or withhold, an official act, or"],[1,"(2) influences, or offers or threatens to influence, the official act of another,"],[0,"shall be fined under this title or imprisoned for not more than 15 years, or both, and may be disqualified from holding any office of honor, trust, or profit under the United States."],[0,"(b) In this section, the term \"covered government person\" means—"],[1,"(1) a Senator or Representative in, or a Delegate or Resident Commissioner to, the Congress;"],[1,"(2) an employee of either House of Congress; or"],[1,"(3) the President, Vice President, an employee of the United States Postal Service or the Postal Regulatory Commission, or any other executive branch employee (as such term is defined under section 2105 of title 5, United States Code)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/227?type=usc&year=mostrecent&link-type=html"},"head":"§227. Wrongfully influencing a private entity's employment decisions by a Member of Congress or an officer or employee of the legislative or executive branch","tname":"Crimes and Criminal Procedure","by":{"1":"25","2":"21"}},{"t":"usc","label":"18 U.S.C. § 607","url":"https://www.law.cornell.edu/uscode/text/18/607","subs":["(a)(1)"],"stext":{"head":"§607. Place of solicitation","paras":[[0,"(a) Prohibition.—"],[1,"(1) In general.—It shall be unlawful for any person to solicit or receive a donation of money or other thing of value in connection with a Federal, State, or local election from a person who is located in a room or building occupied in the discharge of official duties by an officer or employee of the United States. It shall be unlawful for an individual who is an officer or employee of the Federal Government, including the President, Vice President, and Members of Congress, to solicit or receive a donation of money or other thing of value in connection with a Federal, State, or local election, while in any room or building occupied in the discharge of official duties by an officer or employee of the United States, from any person."],[1,"(2) Penalty.—A person who violates this section shall be fined not more than $5,000, imprisoned not more than 3 years, or both."],[0,"(b) The prohibition in subsection (a) shall not apply to the receipt of contributions by persons on the staff of a Senator or Representative in, or Delegate or Resident Commissioner to, the Congress or Executive Office of the President, provided, that such contributions have not been solicited in any manner which directs the contributor to mail or deliver a contribution to any room, building, or other facility referred to in subsection (a), and provided that such contributions are transferred within seven days of receipt to a political committee within the meaning of section 302(e) of the Federal Election Campaign Act of 1971."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/607?type=usc&year=mostrecent&link-type=html"},"head":"§607. Place of solicitation","tname":"Crimes and Criminal Procedure","by":{"1":"25","2":"21"}},{"t":"usc","label":"18 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/18/1111","stext":{"head":"§1111. Murder","paras":[[0,"(a) Murder is the unlawful killing of a human being with malice aforethought. Every murder perpetrated by poison, lying in wait, or any other kind of willful, deliberate, malicious, and premeditated killing; or committed in the perpetration of, or attempt to perpetrate, any arson, escape, murder, kidnapping, treason, espionage, sabotage, aggravated sexual abuse or sexual abuse, child abuse, burglary, or robbery; or perpetrated as part of a pattern or practice of assault or torture against a child or children; or perpetrated from a premeditated design unlawfully and maliciously to effect the death of any human being other than him who is killed, is murder in the first degree."],[0,"Any other murder is murder in the second degree."],[0,"(b) Within the special maritime and territorial jurisdiction of the United States,"],[0,"Whoever is guilty of murder in the first degree shall be punished by death or by imprisonment for life;"],[0,"Whoever is guilty of murder in the second degree, shall be imprisoned for any term of years or for life."],[0,"(c) For purposes of this section—"],[1,"(1) the term \"assault\" has the same meaning as given that term in section 113;"],[1,"(2) the term \"child\" means a person who has not attained the age of 18 years and is—"],[2,"(A) under the perpetrator's care or control; or"],[2,"(B) at least six years younger than the perpetrator;"],[1,"(3) the term \"child abuse\" means intentionally or knowingly causing death or serious bodily injury to a child;"],[1,"(4) the term \"pattern or practice of assault or torture\" means assault or torture engaged in on at least two occasions;"],[1,"(5) the term \"serious bodily injury\" has the meaning set forth in section 1365; and"],[1,"(6) the term \"torture\" means conduct, whether or not committed under the color of law, that otherwise satisfies the definition set forth in section 2340(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1111?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1111. Murder","tname":"Crimes and Criminal Procedure","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 2381","url":"https://www.law.cornell.edu/uscode/text/18/2381","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 2384","url":"https://www.law.cornell.edu/uscode/text/18/2384","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 1913","url":"https://www.law.cornell.edu/uscode/text/18/1913","stext":{"head":"§1913. Lobbying with appropriated moneys","paras":[[0,"No part of the money appropriated by any enactment of Congress shall, in the absence of express authorization by Congress, be used directly or indirectly to pay for any personal service, advertisement, telegram, telephone, letter, printed or written matter, or other device, intended or designed to influence in any manner a Member of Congress, a jurisdiction, or an official of any government, to favor, adopt, or oppose, by vote or otherwise, any legislation, law, ratification, policy, or appropriation, whether before or after the introduction of any bill, measure, or resolution proposing such legislation, law, ratification, policy, or appropriation; but this shall not prevent officers or employees of the United States or of its departments or agencies from communicating to any such Member or official, at his request, or to Congress or such official, through the proper official channels, requests for any legislation, law, ratification, policy, or appropriations which they deem necessary for the efficient conduct of the public business, or from making any communication whose prohibition by this section might, in the opinion of the Attorney General, violate the Constitution or interfere with the conduct of foreign policy, counter-intelligence, intelligence, or national security activities. Violations of this section shall constitute violations of section 1352(a) of title 31."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1913?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1913. Lobbying with appropriated moneys","tname":"Crimes and Criminal Procedure","by":{"1":"28"}},{"t":"reg","label":"64 Fed. Reg. 37,038","url":"https://www.govinfo.gov/link/fr/64/37038","by":{"1":"21"}},{"t":"case","label":"Hunter v. Bryant","cite":"502 U.S. 224","y":1991,"id":"1991/90-1440","sc":1,"sum":"Petitioners are entitled to qualified immunity. They are shielded from suit because a reasonable officer could have believed the arrest to be lawful in light of clearly established law and the information the agents possessed. Anderson v. Creighton, 483 U. S. 635, 641. On the basis of that information, a Magistrate ordered Bryant held without bond. Even assuming that they erred in concluding that probable cause …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"op":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"op":2,"ar":1,"sum":"Explaining that questions of immunity are reviewable before trial because the essence of immunity is the entitlement not to be subject to suit.","sumSrc":"opinion","by":{"2":"24"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"sum":"Bribery of private employees prohibited by state criminal statutes violates the Travel Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"sum":"From the allegations of the complaint, it appears that petitioners were acting in a field where legislators traditionally have power to act; and 8 U. S. C. §§ 43 and 47 (3) do not create civil liability for such conduct.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"United States v. Brewster","cite":"408 U.S. 501","y":1972,"id":"1971/70-45","sc":1,"ar":7,"sum":"Appellee, a former United States Senator, was charged with the solicitation and acceptance of bribes in violation of 18 U. S. C. §§ 201 (c) (1) and 201 (g). T-he District Court, on appellee's pretrial motion, dismissed the indictment on the ground that the Speech or Debate Clause of the Constitution shielded him \"from any prosecution for alleged bribery to perform a legislative act.\" The United States filed a direct …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11, 14, 21, 23-24"}},{"t":"case","label":"United States v. Chaplin","cite":"54 F. Supp. 926","y":1944,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./54/926/","by":{"2":"14"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"op":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"1, 19"}},{"t":"case","label":"Vt. Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"op":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"2":"7"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":15,"ar":1,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"2":"20"}},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(1)(A)(iv)"],"by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 1119","url":"https://www.law.cornell.edu/uscode/text/18/1119","subs":["(b)"],"by":{"2":"17"}}]};